"""More scam and cyber-fraud families (part 2) for the scam-methods catalogue. Same shape as scams_data.DATA:
key -> (aliases, (name, what, example, protect) in en, fr, rw, sw). Examples are invented illustrations, not real messages or organisations.
Protective text only (recognise and resist); fr/rw/sw wording is a draft for fluent review."""


def S(aliases, en, fr, rw, sw):
    return (aliases, en, fr, rw, sw)


EXTRA = {
"fakedelivery": S(["fake delivery scam", "parcel scam", "package scam", "customs fee scam", "delivery fee scam", "courier scam"],
  ("Fake delivery and customs-fee scam", "A message or call says a parcel or gift from abroad is held and you must pay a small delivery, customs or storage fee to release it.", "“Your parcel is held. Pay 3,500 RWF at this link to confirm delivery.” There is no parcel; the link steals your card or mobile-money details.", "Only pay through the courier's official app or website you reach yourself; check whether you really expect a parcel, never pay fees for gifts from strangers."),
  ("Arnaque au faux colis et frais de douane", "Un message ou appel dit qu'un colis ou cadeau de l'étranger est bloqué et qu'il faut payer de petits frais de livraison, de douane ou de stockage.", "« Votre colis est retenu. Payez 3 500 RWF via ce lien pour confirmer la livraison. » Il n'y a pas de colis ; le lien vole vos données de carte ou d'argent mobile.", "Ne payez que via l'application ou le site officiel du transporteur atteint par vous-même ; vérifiez si vous attendez vraiment un colis et ne payez jamais de frais pour un cadeau d'un inconnu."),
  ("Uburiganya bw'ipaki y'impimbano n'amafaranga ya gasutamo", "Ubutumwa cyangwa guhamagara bivuga ko ipaki cyangwa impano ivuye hanze yafashwe ukwiye kwishyura amafaranga make yo kohereza, gasutamo cyangwa kubika.", "«Ipaki yawe irafashwe. Ishyura 3,500 RWF kuri iyi link wemeze kuyibona.» Nta paki ihari; link yiba amakuru ya karita cyangwa mobile money.", "Ishyura gusa unyuze ku porogaramu cyangwa urubuga rwemewe rw'ikigo gitwara wowe ubwawe wageraho; genzura niba utegereje ipaki koko, ntukishyure amafaranga ku mpano y'utazi."),
  ("Ulaghai wa kifurushi bandia na ada ya forodha", "Ujumbe au simu inasema kifurushi au zawadi kutoka nje imekamatwa na lazima ulipe ada ndogo ya uwasilishaji, forodha au kuhifadhi ili kiachiliwe.", "«Kifurushi chako kimezuiliwa. Lipa 3,500 RWF kupitia kiungo hiki kuthibitisha uwasilishaji.» Hakuna kifurushi; kiungo huiba taarifa za kadi au pesa za simu.", "Lipa kupitia programu au tovuti rasmi ya msafirishaji uliyoifikia mwenyewe; kagua kama kweli unatarajia kifurushi, kamwe usilipe ada kwa zawadi ya mgeni.")),
"govfine": S(["fake government fine", "fake fine", "fake tax refund", "fake traffic fine", "police fine scam", "government impersonation scam", "tax scam"],
  ("Fake government fine, tax or refund scam", "A message pretending to come from the police, tax office or another authority claims you owe a fine or are owed a refund and asks you to pay or enter your details by link.", "“Traffic fine unpaid: pay within 24 hours to avoid arrest.” The authority never collects fines or refunds through random links or personal mobile numbers.", "Check any fine or refund directly on the official government portal or office; do not pay through links or to personal numbers, and ignore threats of arrest by text."),
  ("Fausse amende, fausse taxe ou faux remboursement", "Un message se faisant passer pour la police, les impôts ou une autre autorité prétend que vous devez une amende ou avez droit à un remboursement et demande de payer ou saisir vos données par un lien.", "« Amende routière impayée : payez sous 24 h pour éviter l'arrestation. » Les autorités ne perçoivent pas d'amendes ou remboursements par des liens inconnus ou des numéros personnels.", "Vérifiez toute amende ou remboursement directement sur le portail ou le bureau officiel ; ne payez ni par lien ni vers un numéro personnel et ignorez les menaces d'arrestation par SMS."),
  ("Uburiganya bw'ihazabu, imisoro cyangwa gusubizwa amafaranga by'impimbano", "Ubutumwa bwiyitirira polisi, ikigo cy'imisoro cyangwa ubundi buyobozi buvuga ko ufite ihazabu cyangwa ugomba gusubizwa amafaranga, bugasaba kwishyura cyangwa gushyira amakuru kuri link.", "«Ihazabu yo mu muhanda ntiyishyuwe: ishyura mu masaha 24 wirinde gufungwa.» Ubuyobozi ntibukusanya ihazabu cyangwa gusubiza amafaranga unyuze kuri link zitazwi cyangwa nimero bwite.", "Genzura ihazabu cyangwa gusubizwa amafaranga ku rubuga cyangwa ku biro byemewe; ntukishyure unyuze kuri link cyangwa kuri nimero bwite kandi wirengagize iterabwoba ryo gufungwa mu butumwa."),
  ("Ulaghai wa faini, kodi au marejesho bandia", "Ujumbe unaojifanya polisi, mamlaka ya kodi au mamlaka nyingine unadai una faini au unastahili kurejeshewa na kukuomba ulipe au uweke taarifa kwa kiungo.", "«Faini ya barabarani haijalipwa: lipa ndani ya saa 24 kuepuka kukamatwa.» Mamlaka hazikusanyi faini au marejesho kupitia viungo holela au namba binafsi.", "Hakiki faini au marejesho moja kwa moja kwenye tovuti au ofisi rasmi; usilipe kupitia viungo au kwa namba binafsi na puuza vitisho vya kukamatwa kwa ujumbe.")),
"mistakenpayment": S(["mistaken transfer scam", "sent by mistake scam", "wrong number refund scam", "mistaken payment scam", "reverse transaction scam", "money sent by mistake"],
  ("Money 'sent by mistake' scam", "A fake mobile-money confirmation or a call says money was sent to you by mistake and asks you to send it back, but no money really arrived, or the payment will later be reversed.", "“I sent you 50,000 RWF by mistake, please return it.” You send your real money back and lose it.", "Check your balance yourself with the official USSD or app, not the message; never 'return' money until your provider confirms it and ask them to reverse it."),
  ("Arnaque de l'argent « envoyé par erreur »", "Une fausse confirmation d'argent mobile ou un appel dit qu'on vous a envoyé de l'argent par erreur et demande de le renvoyer, mais rien n'est arrivé ou le paiement sera annulé plus tard.", "« Je vous ai envoyé 50 000 RWF par erreur, merci de les renvoyer. » Vous renvoyez votre vrai argent et vous le perdez.", "Vérifiez vous-même votre solde via l'USSD ou l'application officielle, pas le message ; ne « renvoyez » rien avant confirmation de votre opérateur et demandez-lui d'annuler la transaction."),
  ("Uburiganya bwo «kohereza amafaranga kubw'ikosa»", "Ubutumwa bw'impimbano bwa mobile money cyangwa guhamagara bivuga ko wohererejwe amafaranga kubw'ikosa bugasaba ko uyasubiza, nyamara nta mafaranga yaje cyangwa azasubizwa nyuma.", "«Nakohereje 50,000 RWF kubw'ikosa, nyasubiza nyabuneka.» Wohereza amafaranga yawe nyayo ukayatakaza.", "Reba konti yawe ubwawe ukoresheje USSD cyangwa porogaramu yemewe, si ubutumwa; ntugasubize amafaranga mbere y'uko utanga serivisi abyemeza kandi musabe gusubiza igikorwa."),
  ("Ulaghai wa pesa «zilizotumwa kimakosa»", "Ujumbe bandia wa uthibitisho wa pesa za simu au simu inasema pesa zimetumwa kwako kimakosa na kukuomba uzirudishe, lakini hakuna pesa zilizofika au malipo yatarudishwa baadaye.", "«Nilikutumia 50,000 RWF kimakosa, tafadhali nirudishie.» Unatuma pesa zako halisi na kuzipoteza.", "Angalia salio lako mwenyewe kwa USSD au programu rasmi, si ujumbe; usirudishe pesa kabla mtoa huduma kuthibitisha na umwombe abatilishe muamala.")),
"ponzi": S(["ponzi scheme", "pyramid scheme", "pyramid scam", "ponzi scam", "get rich quick scheme", "recruit others scheme", "multi level marketing scam"],
  ("Ponzi and pyramid schemes", "Schemes that promise high, fast, 'guaranteed' returns paid mainly with money from newer members; they collapse when recruitment slows and most people lose their money.", "“Invest 100,000 RWF and get 200,000 in a month; invite friends for bonuses.”", "Be suspicious of guaranteed or unusually high returns and of pay-for-recruiting; check that the business is licensed with the financial regulator and never invest money you cannot afford to lose."),
  ("Systèmes de Ponzi et pyramidaux", "Systèmes qui promettent des rendements élevés, rapides et « garantis », payés surtout avec l'argent des nouveaux membres ; ils s'effondrent quand le recrutement ralentit et la plupart perdent leur argent.", "« Investissez 100 000 RWF et recevez 200 000 en un mois ; invitez des amis pour des bonus. »", "Méfiez-vous des rendements garantis ou anormalement élevés et de la rémunération par recrutement ; vérifiez que l'entreprise est agréée par le régulateur financier et n'investissez jamais ce que vous ne pouvez pas perdre."),
  ("Gahunda za Ponzi na pyramid", "Gahunda zisezeranya inyungu nyinshi, zihuse kandi «z'ingwate» zishyurwa cyane n'amafaranga y'abinjiyemo vuba; zirasenyuka iyo gushaka abanyamuryango bigabanutse abenshi bagatakaza amafaranga.", "«Shora 100,000 RWF ubone 200,000 mu kwezi; tumira inshuti ubone bonus.»", "Gira amakenga ku nyungu z'ingwate cyangwa nyinshi cyane no kwishyurwa ku gushaka abandi; genzura ko ikigo gifite uruhushya rw'urwego rugenzura imari kandi ntuzigere ushora amafaranga udashobora gutakaza."),
  ("Mipango ya Ponzi na pyramid", "Mipango inayoahidi faida kubwa, za haraka na «za uhakika» zinazolipwa hasa kwa pesa za wanachama wapya; huanguka kuajiri kukipungua na wengi hupoteza pesa zao.", "«Wekeza 100,000 RWF upate 200,000 kwa mwezi; alika marafiki kwa bonasi.»", "Shuku faida za uhakika au kubwa isivyo kawaida na malipo ya kuajiri; hakiki biashara ina leseni kwa mdhibiti wa fedha na usiwekeze pesa usizoweza kupoteza.")),
"loanapp": S(["loan app scam", "instant loan app scam", "fake loan app", "loan app harassment", "predatory loan app", "digital loan scam"],
  ("Predatory and fake loan apps", "Apps that offer quick loans but ask for access to contacts and photos, charge hidden fees or huge interest, or never lend at all; some harass borrowers and their contacts for repayment.", "An app asks for an 'insurance fee' before releasing a loan, then threatens to message your contacts.", "Use only licensed lenders; read the total cost and permissions before agreeing, never pay a fee to receive a loan, and report harassment to the regulator and police."),
  ("Applications de prêt prédatrices ou fausses", "Applications qui offrent des prêts rapides mais demandent l'accès aux contacts et photos, facturent des frais cachés ou des intérêts énormes, ou ne prêtent jamais ; certaines harcèlent les emprunteurs et leurs contacts.", "Une appli demande des « frais d'assurance » avant de verser le prêt, puis menace d'écrire à vos contacts.", "Utilisez uniquement des prêteurs agréés ; lisez le coût total et les permissions avant d'accepter, ne payez jamais de frais pour recevoir un prêt et signalez le harcèlement au régulateur et à la police."),
  ("Porogaramu z'inguzanyo zibangamira cyangwa z'impimbano", "Porogaramu zitanga inguzanyo ihuse ariko zisaba kugera ku contacts n'amafoto, zigatwara amafaranga yihishe cyangwa inyungu nyinshi cyangwa ntizitange inguzanyo; zimwe zibangamira abagurijwe n'abo bazi.", "Porogaramu isaba «amafaranga y'ubwishingizi» mbere yo gutanga inguzanyo, hanyuma igatera ubwoba ko izandikira contacts zawe.", "Koresha abatanga inguzanyo bafite uruhushya gusa; soma igiciro cyose n'uburenganzira mbere yo kwemera, ntukishyure amafaranga ngo ubone inguzanyo kandi umenyeshe urwego rugenzura na polisi iyo ubangamiwe."),
  ("Programu za mikopo za unyonyaji au bandia", "Programu zinazotoa mikopo ya haraka lakini zinaomba ufikiaji wa anwani na picha, kutoza ada zilizofichwa au riba kubwa, au hazikopeshi kamwe; baadhi hunyanyasa wakopaji na watu wao.", "Programu inaomba «ada ya bima» kabla ya kutoa mkopo, kisha inatishia kuwatumia ujumbe watu wako.", "Tumia wakopeshaji wenye leseni tu; soma gharama yote na ruhusa kabla ya kukubali, kamwe usilipe ada kupokea mkopo na ripoti unyanyasaji kwa mdhibiti na polisi.")),
"visascam": S(["visa scam", "immigration scam", "job abroad scam", "overseas job scam", "fake visa offer", "travel agency scam", "study abroad scam"],
  ("Visa, immigration and job-abroad scams", "Fake agents promise a visa, a work contract or a scholarship abroad in return for fees, then disappear or keep asking for more money.", "“Guaranteed visa to Canada and a job: pay 800,000 RWF to our agent today.”", "Verify agents with the embassy or the official government immigration site, pay only through traceable official channels, get written contracts and never send passports or fees to unverified people."),
  ("Arnaques visa, immigration et emploi à l'étranger", "De faux agents promettent un visa, un contrat de travail ou une bourse à l'étranger contre des frais, puis disparaissent ou réclament toujours plus d'argent.", "« Visa garanti pour le Canada et un emploi : payez 800 000 RWF à notre agent aujourd'hui. »", "Vérifiez les agents auprès de l'ambassade ou du site officiel d'immigration, ne payez que par des canaux officiels traçables, exigez des contrats écrits et n'envoyez ni passeport ni frais à des inconnus."),
  ("Uburiganya bwa viza, immigration n'akazi hanze", "Abakozi b'impimbano basezeranya viza, amasezerano y'akazi cyangwa buruse hanze bagasaba amafaranga, hanyuma bakabura cyangwa bagakomeza gusaba andi.", "«Viza ya Canada n'akazi by'ingwate: ishyura 800,000 RWF umukozi wacu uyu munsi.»", "Genzura abakozi kuri ambasade cyangwa urubuga rwemewe rw'abinjira n'abasohoka, ishyura gusa unyuze mu nzira zemewe zikurikiranwa, usabe amasezerano yanditse kandi ntuzohereze pasiporo cyangwa amafaranga ku bantu batagenzuwe."),
  ("Ulaghai wa viza, uhamiaji na kazi nje ya nchi", "Mawakala bandia huahidi viza, mkataba wa kazi au ufadhili nje ya nchi kwa malipo, kisha hupotea au kuendelea kuomba pesa zaidi.", "«Viza ya uhakika ya Canada na kazi: lipa 800,000 RWF kwa wakala wetu leo.»", "Hakiki mawakala kwa ubalozi au tovuti rasmi ya uhamiaji, lipa kwa njia rasmi zinazofuatilika tu, dai mikataba ya maandishi na usitume pasipoti wala ada kwa watu wasiohakikiwa.")),
"cryptoscam": S(["crypto scam", "cryptocurrency scam", "rug pull", "fake crypto exchange", "fake crypto wallet", "crypto investment scam", "bitcoin scam", "fake token"],
  ("Cryptocurrency scams (fake exchanges, rug pulls, fake wallets)", "Criminals use fake trading platforms, 'guaranteed profit' bots, new tokens whose creators vanish with the money (rug pull) and fake wallet apps that steal recovery phrases.", "A website shows growing profits but blocks withdrawals until you pay 'tax' or a 'fee'.", "Never share your recovery phrase or private key, use well-known regulated platforms, test withdrawals with small amounts and ignore promises of guaranteed crypto profits."),
  ("Arnaques aux cryptomonnaies (faux échanges, rug pulls, faux portefeuilles)", "Les criminels utilisent de fausses plateformes, des bots à « profit garanti », de nouveaux jetons dont les créateurs disparaissent avec l'argent (rug pull) et de faux portefeuilles qui volent les phrases de récupération.", "Un site affiche des gains croissants mais bloque les retraits tant que vous ne payez pas une « taxe » ou des « frais ».", "Ne partagez jamais votre phrase de récupération ou clé privée, utilisez des plateformes connues et régulées, testez les retraits avec de petits montants et ignorez les promesses de profits garantis."),
  ("Uburiganya bwa cryptocurrency (impimbano z'ubucuruzi, rug pull, wallets z'impimbano)", "Abagizi ba nabi bakoresha imbuga z'impimbano zo gucuruza, bots «z'inyungu z'ingwate», token nshya abazikoze bashira bafite amafaranga (rug pull) na porogaramu za wallet z'impimbano ziba interuro zo gusubiza konti.", "Urubuga rwerekana inyungu zizamuka ariko rukanga gukuramo kugeza wishyuye «umusoro» cyangwa «amafaranga».", "Ntuzigere usangiza interuro yo gusubiza konti cyangwa urufunguzo rwihariye, koresha imbuga zizwi kandi zigenzurwa, gerageza gukuramo amafaranga make kandi wirengagize ibyizeza inyungu z'ingwate."),
  ("Ulaghai wa sarafu za kidijitali (soko bandia, rug pull, pochi bandia)", "Wahalifu hutumia majukwaa bandia ya biashara, boti za «faida ya uhakika», tokeni mpya ambazo waundaji hutoweka na pesa (rug pull) na programu bandia za pochi zinazoiba maneno ya kurejesha.", "Tovuti inaonyesha faida zinazoongezeka lakini inazuia kutoa hadi ulipe «kodi» au «ada».", "Kamwe usishiriki maneno ya kurejesha au ufunguo wa faragha, tumia majukwaa yanayojulikana na kudhibitiwa, jaribu kutoa kiasi kidogo na puuza ahadi za faida ya uhakika.")),
"pigbutchering": S(["pig butchering", "pig butchering scam", "long con investment scam", "wrong number investment scam", "romance investment scam"],
  ("Pig butchering (long-con romance and investment fraud)", "A scammer builds weeks of friendship or romance after a 'wrong number' message, then guides the victim to a fake investment platform, lets small profits be withdrawn and finally takes everything.", "A friendly stranger on chat shares 'their uncle's' trading tips and a website where your balance keeps growing.", "Be wary of a stranger who moves a friendship toward investing, never invest on platforms recommended by online contacts, and talk to family before sending large sums."),
  ("Pig butchering (fraude sentimentale et d'investissement de longue haleine)", "Un escroc noue pendant des semaines une amitié ou romance après un message « mauvais numéro », puis oriente la victime vers une fausse plateforme d'investissement, laisse retirer de petits gains et finit par tout prendre.", "Un inconnu sympathique partage les « conseils de trading de son oncle » et un site où votre solde grossit sans cesse.", "Méfiez-vous d'un inconnu qui oriente l'amitié vers l'investissement, n'investissez jamais sur des plateformes recommandées par des contacts en ligne et parlez à votre famille avant d'envoyer de grosses sommes."),
  ("Pig butchering (uburiganya bw'urukundo n'ishoramari bumara igihe)", "Umutekamutwe yubaka ubucuti cyangwa urukundo mu byumweru nyuma y'ubutumwa bwa «nimero itari yo», hanyuma akoherereza uwo yibasiye ku rubuga rw'ishoramari rw'impimbano, akamureka agakuramo inyungu nke, amaherezo akamwambura byose.", "Umuntu utazwi ukunzwe asangiza «inama z'ubucuruzi za nyirarume» n'urubuga aho amafaranga yawe akomeza kwiyongera.", "Gira amakenga ku utazwi uhindura ubucuti ishoramari, ntuzigere ushora ku mbuga zasabwe n'abo muhura kuri interineti kandi ubaze umuryango mbere yo kohereza amafaranga menshi."),
  ("Pig butchering (ulaghai wa mapenzi na uwekezaji wa muda mrefu)", "Tapeli hujenga urafiki au mapenzi kwa wiki baada ya ujumbe wa «namba isiyo sahihi», kisha kumwongoza mwathirika kwenye jukwaa bandia la uwekezaji, kumruhusu kutoa faida ndogo na hatimaye kuchukua kila kitu.", "Mgeni mpole kwenye mazungumzo anashiriki «ushauri wa biashara wa mjomba wake» na tovuti ambapo salio lako linaendelea kukua.", "Kuwa makini na mgeni anayeelekeza urafiki kwenye uwekezaji, kamwe usiwekeze kwenye majukwaa yaliyopendekezwa na watu wa mtandaoni na zungumza na familia kabla ya kutuma kiasi kikubwa.")),
"faketender": S(["fake tender scam", "procurement scam", "fake supplier scam", "fake contract scam", "fake purchase order", "tender fee scam"],
  ("Fake tender and purchase-order scams", "Fraudsters send fake tender notices or large purchase orders to small businesses, ask for registration, bid or 'sample' fees or a deposit, then vanish.", "A big 'company' orders 500 bags of maize but asks you to pay for a 'supplier verification' first.", "Verify tenders on the official procurement portal, call the buyer using details you find yourself, never pay to win a contract and ask for written proof of the order before spending money."),
  ("Faux appels d'offres et bons de commande", "Des fraudeurs envoient aux petites entreprises de faux appels d'offres ou de gros bons de commande, demandent des frais d'inscription, de soumission, d'« échantillons » ou un acompte, puis disparaissent.", "Une grande « société » commande 500 sacs de maïs mais demande d'abord de payer une « vérification de fournisseur ».", "Vérifiez les appels d'offres sur le portail officiel des marchés, appelez l'acheteur avec des coordonnées trouvées par vous-même, ne payez jamais pour gagner un contrat et exigez une preuve écrite avant de dépenser."),
  ("Uburiganya bw'amasoko y'impimbano n'amabwiriza yo kugura", "Abatekamutwe bohereza ku bacuruzi bato ibitangazo by'amasoko cyangwa amabwiriza manini yo kugura by'impimbano, bagasaba amafaranga yo kwiyandikisha, gupiganwa, «sample» cyangwa avansi, hanyuma bagashira.", "«Ikigo» kinini gitumiza imifuka 500 y'ibigori ariko kigasaba ko banza wishyura «kugenzura utanga ibicuruzwa».", "Genzura amasoko ku rubuga rwemewe rw'amasoko ya leta, uhamagare uwaguze ukoresheje amakuru wibonyeye, ntukishyure ngo ubone isoko kandi usabe gihamya yanditse mbere yo gukoresha amafaranga."),
  ("Ulaghai wa zabuni na maagizo ya ununuzi bandia", "Walaghai hutuma notisi za zabuni bandia au maagizo makubwa ya ununuzi kwa biashara ndogo, kuomba ada za usajili, zabuni, «sampuli» au amana, kisha kutoweka.", "«Kampuni» kubwa inaagiza magunia 500 ya mahindi lakini inakuomba kwanza ulipie «uhakiki wa msambazaji».", "Hakiki zabuni kwenye lango rasmi la manunuzi, piga mnunuzi kwa mawasiliano uliyoyapata mwenyewe, kamwe usilipe ili kushinda mkataba na dai uthibitisho wa maandishi kabla ya kutumia pesa.")),
"domainrenewal": S(["domain renewal scam", "business directory scam", "fake invoice domain", "website renewal scam", "seo scam", "fake seo offer"],
  ("Domain renewal, directory and fake SEO scams", "A business gets an official-looking 'renewal notice' or invoice for a domain, directory listing or search ranking it never ordered, hoping staff pay without checking.", "“Your domain expires in 3 days: pay 150 USD to the registry.” The sender is not your registrar.", "Check renewals only in your own registrar or hosting account, route all invoices through a verification step and ignore unsolicited ranking or listing offers."),
  ("Arnaques au renouvellement de domaine, annuaires et faux SEO", "Une entreprise reçoit un « avis de renouvellement » ou une facture d'apparence officielle pour un domaine, un annuaire ou un référencement jamais commandé, en espérant que le personnel paie sans vérifier.", "« Votre domaine expire dans 3 jours : payez 150 USD au registre. » L'expéditeur n'est pas votre registrar.", "Vérifiez les renouvellements uniquement dans votre propre compte registrar ou d'hébergement, faites vérifier toutes les factures et ignorez les offres non sollicitées de référencement."),
  ("Uburiganya bwo kongera domain, directory na SEO y'impimbano", "Ikigo gihabwa «itangazo ryo kongera» cyangwa fagitire isa n'iyemewe ya domain, directory cyangwa kugaragara muri moteri ishakisha batigeze batumiza, byiringiwe ko abakozi bazishyura batagenzuye.", "«Domain yawe irarangira mu minsi 3: ishyura 150 USD ku registry.» Uwohereje si registrar wawe.", "Genzura kongera gusa muri konti yawe bwite ya registrar cyangwa hosting, ushyireho intambwe yo kugenzura fagitire zose kandi wirengagize ibyifuzo bitasabwe byo kugaragara."),
  ("Ulaghai wa upyaishaji wa kikoa, saraka na SEO bandia", "Biashara hupokea «notisi ya upyaishaji» au ankara inayoonekana rasmi kwa kikoa, saraka au nafasi ya utafutaji ambayo haijaagiza, wakitumaini wafanyakazi walipe bila kuhakiki.", "«Kikoa chako kinaisha siku 3: lipa USD 150 kwa msajili.» Mtumaji si msajili wako.", "Hakiki upyaishaji kwenye akaunti yako ya msajili au hosting pekee, pitisha ankara zote kwenye hatua ya uhakiki na puuza ofa zisizoombwa za nafasi au orodha.")),
"moneymule": S(["money mule", "money mule scam", "receive and forward money job", "payment processing job scam", "easy money transfer job"],
  ("Money mule recruitment", "Criminals offer an 'easy job' or a commission to receive money in your account or mobile-money wallet and forward it, which launders stolen money; the mule is the one traced by police.", "“Receive payments for our company and send 90% on, keep 10%.”", "Never let anyone use your account or wallet to move money, refuse jobs that involve receiving and forwarding payments and report such offers; you can be prosecuted even if you did not know."),
  ("Recrutement de « mules financières »", "Des criminels proposent un « travail facile » ou une commission pour recevoir de l'argent sur votre compte ou portefeuille mobile et le transférer, ce qui blanchit de l'argent volé ; c'est la mule que la police retrouve.", "« Recevez des paiements pour notre société et renvoyez-en 90 %, gardez 10 %. »", "Ne laissez jamais personne utiliser votre compte ou portefeuille pour déplacer de l'argent, refusez les emplois consistant à recevoir et transférer des paiements et signalez ces offres ; vous pouvez être poursuivi même sans le savoir."),
  ("Gushaka «money mules»", "Abagizi ba nabi batanga «akazi koroshye» cyangwa komisiyo yo kwakira amafaranga kuri konti yawe cyangwa mobile money ukayohereza, bihindura amafaranga yibwe; uwo bafata ni mule.", "«Akira amafaranga y'ikigo cyacu uyohereze 90%, usigarane 10%.»", "Ntuzigere ureka umuntu akoresha konti yawe cyangwa wallet kwimura amafaranga, wange akazi ko kwakira no kohereza amafaranga kandi ubimenyeshe; ushobora kuregwa nubwo utabizi."),
  ("Kuajiri «money mule»", "Wahalifu hutoa «kazi rahisi» au kamisheni ya kupokea pesa kwenye akaunti au pochi yako ya simu na kuzituma, ambayo husafisha pesa zilizoibiwa; mule ndiye anayefuatiliwa na polisi.", "«Pokea malipo kwa kampuni yetu na utume 90%, baki na 10%.»", "Kamwe usimruhusu mtu atumie akaunti au pochi yako kuhamisha pesa, kataa kazi za kupokea na kutuma malipo na ripoti ofa hizo; unaweza kushtakiwa hata bila kujua.")),
"virtualkidnap": S(["virtual kidnapping", "fake kidnapping scam", "kidnap call scam", "fake emergency call ransom", "relative kidnapped scam", "family member arrested scam"],
  ("Virtual kidnapping and fake-arrest calls", "A caller says a relative has been kidnapped, arrested or injured and demands money at once, sometimes with a cloned voice crying in the background, hoping panic stops you checking.", "“We have your son; send money now and do not hang up.” He is actually safe at school.", "Stay calm, hang up and call the relative or someone near them directly, agree a family safe word and never send money to a caller under pressure; report to the police."),
  ("Faux enlèvement et faux appels d'arrestation", "Un appelant dit qu'un proche est enlevé, arrêté ou blessé et exige de l'argent aussitôt, parfois avec une voix clonée qui pleure en fond, en espérant que la panique vous empêche de vérifier.", "« Nous avons votre fils ; envoyez de l'argent maintenant et ne raccrochez pas. » En réalité il est à l'école en sécurité.", "Restez calme, raccrochez et appelez directement le proche ou quelqu'un près de lui, convenez d'un mot de passe familial et n'envoyez jamais d'argent sous pression ; signalez à la police."),
  ("Gushimutwa kw'impimbano n'ihamagara ry'ifungwa ry'impimbano", "Uhamagara avuga ko mu muryango hari washimuswe, wafunzwe cyangwa wakomeretse agasaba amafaranga ako kanya, rimwe na rimwe hari ijwi ryakopowe rirurira inyuma, yizeye ko ubwoba buzakubuza kugenzura.", "«Dufite umuhungu wawe; ohereza amafaranga nonaha kandi ntucibwe.» Nyamara ari ku ishuri ari mu mutekano.", "Tuza, uce uhamagare ako kanya uwo muryango cyangwa umuntu umuri hafi, mwemeranye ijambo ry'ibanga ry'umuryango kandi ntuzohereze amafaranga ku muhamagaye mu bwoba; menyesha polisi."),
  ("Utekaji nyara wa uongo na simu bandia za kukamatwa", "Mpigaji anasema ndugu ametekwa, amekamatwa au amejeruhiwa na kudai pesa mara moja, wakati mwingine na sauti iliyonakiliwa ikilia nyuma, akitumaini hofu itakuzuia kuhakiki.", "«Tunaye mwanao; tuma pesa sasa na usikate simu.» Kumbe yuko salama shuleni.", "Tulia, kata simu na umpigie ndugu au mtu aliye karibu naye moja kwa moja, kubaliane neno la siri la familia na kamwe usitume pesa kwa mpigaji chini ya shinikizo; ripoti polisi.")),
"freedata": S(["free data scam", "free internet scam", "free airtime scam", "free wifi offer scam", "free data offer", "free gift whatsapp scam"],
  ("Free data, airtime and gift offers", "Viral messages promise free internet bundles, airtime or gifts 'from the operator' if you click a link, share the message with contacts or fill a survey, which spreads the scam and steals details.", "“MTN gives 10GB free for the anniversary. Click and forward to 10 groups.”", "Operators announce offers on their official channels only; do not click or forward such messages, and never enter personal or mobile-money details to 'claim' a gift."),
  ("Offres de data, crédit et cadeaux gratuits", "Des messages viraux promettent des forfaits internet, du crédit ou des cadeaux gratuits « de l'opérateur » si vous cliquez sur un lien, partagez le message ou remplissez une enquête, ce qui propage l'arnaque et vole des données.", "« MTN offre 10 Go gratuits pour l'anniversaire. Cliquez et transférez à 10 groupes. »", "Les opérateurs annoncent leurs offres uniquement sur leurs canaux officiels ; ne cliquez pas, ne transférez pas ces messages et ne saisissez jamais de données personnelles ou d'argent mobile pour « récupérer » un cadeau."),
  ("Ibyizeza bya data, airtime n'impano z'ubuntu", "Ubutumwa bukwirakwira buvuga data, airtime cyangwa impano z'ubuntu «ziva kuri sosiyete» uramutse ukanze link, usangije ubutumwa cyangwa wuzuza ibibazo, bigakwirakwiza uburiganya kandi bikiba amakuru.", "«MTN itanga 10GB y'ubuntu ku munsi mukuru. Kanda wohereze ku matsinda 10.»", "Sosiyete zitangaza ibyizeza ku miyoboro yazo yemewe gusa; ntukande cyangwa ngo wohereze ubutumwa nk'ubu kandi ntuzigere ushyira amakuru bwite cyangwa ya mobile money ngo «ubone» impano."),
  ("Ofa za data, muda wa maongezi na zawadi bure", "Jumbe zinazosambaa huahidi vifurushi vya intaneti, muda wa maongezi au zawadi bure «kutoka kampuni ya simu» ukibofya kiungo, kushiriki ujumbe au kujaza utafiti, hivyo kueneza ulaghai na kuiba taarifa.", "«MTN inatoa GB 10 bure kwa maadhimisho. Bofya na usambaze kwa makundi 10.»", "Kampuni hutangaza ofa kwenye njia zake rasmi tu; usibofye wala kusambaza jumbe hizo na kamwe usiweke taarifa binafsi au za pesa za simu «kudai» zawadi.")),
"giftcard": S(["gift card scam", "voucher scam", "pay with gift cards", "itunes card scam", "prepaid card scam", "airtime voucher payment scam"],
  ("Gift-card and voucher payment scams", "Scammers insist you pay a 'fine', 'fee' or 'loan' with gift cards, vouchers or airtime codes because these are fast, hard to trace and almost impossible to refund.", "“Buy five 50,000 vouchers and read me the codes to clear your account.” No real organisation does this.", "Treat any request to pay with gift cards, vouchers or airtime as a scam; hang up, tell someone you trust and, if you already paid, contact the card issuer immediately."),
  ("Arnaques au paiement par cartes cadeaux et vouchers", "Les escrocs exigent de payer une « amende », des « frais » ou un « prêt » par cartes cadeaux, vouchers ou codes de crédit car c'est rapide, difficile à tracer et presque impossible à rembourser.", "« Achetez cinq vouchers de 50 000 et lisez-moi les codes pour régulariser votre compte. » Aucune vraie organisation ne fait cela.", "Toute demande de paiement par cartes cadeaux, vouchers ou crédit est une arnaque ; raccrochez, parlez-en à une personne de confiance et, si vous avez payé, contactez immédiatement l'émetteur de la carte."),
  ("Uburiganya bwo kwishyura na gift cards na vouchers", "Abatekamutwe baguhatira kwishyura «ihazabu», «amafaranga» cyangwa «inguzanyo» ukoresheje gift cards, vouchers cyangwa kode za airtime kuko byihuta, bigoye gukurikirana kandi hafi ya byose ntibisubizwa.", "«Gura vouchers eshanu za 50,000 unsomere kode kugira ngo konti yawe isubire ku murongo.» Nta kigo nyacyo gikora ibi.", "Icyifuzo cyose cyo kwishyura na gift cards, vouchers cyangwa airtime ni uburiganya; hagarika guhamagara, ubibwire uwo wizeye kandi niba warishyuye, menyesha utanga ikarita ako kanya."),
  ("Ulaghai wa malipo kwa kadi za zawadi na vocha", "Matapeli hung'ang'ania ulipe «faini», «ada» au «mkopo» kwa kadi za zawadi, vocha au misimbo ya muda wa maongezi kwa sababu ni za haraka, ngumu kufuatilia na karibu haziwezi kurejeshwa.", "«Nunua vocha tano za 50,000 na unisomee misimbo ili akaunti yako irekebishwe.» Hakuna shirika halisi linalofanya hivi.", "Ombi lolote la kulipa kwa kadi za zawadi, vocha au muda wa maongezi ni ulaghai; kata simu, mwambie unayemwamini na ikiwa umeshalipa, wasiliana na mtoaji wa kadi mara moja.")),
"bookingscam": S(["booking scam", "fake hotel booking", "fake accommodation scam", "fake ticket scam", "event ticket scam", "fake travel booking", "airbnb scam", "fake flight ticket"],
  ("Fake booking, ticket and accommodation scams", "Criminals advertise hotels, flats, flights or event tickets that do not exist, or copy a real hotel's booking page, and take payment in advance.", "A beautiful holiday home is offered at half price if you pay a deposit today by mobile money.", "Book only through well-known platforms or the venue's official website, compare the price with the market, avoid paying outside the platform and call the venue using a number you find yourself."),
  ("Fausses réservations, billets et logements", "Des criminels publient des hôtels, appartements, vols ou billets d'événements inexistants, ou copient la page de réservation d'un vrai hôtel, et encaissent un paiement à l'avance.", "Une belle maison de vacances est proposée à moitié prix si vous versez aujourd'hui un acompte par argent mobile.", "Réservez uniquement via des plateformes connues ou le site officiel du lieu, comparez le prix au marché, évitez de payer hors de la plateforme et appelez le lieu avec un numéro trouvé par vous-même."),
  ("Uburiganya bwo gufata ibyumba, amatike n'amacumbi by'impimbano", "Abagizi ba nabi bamamaza amahoteli, amazu, ingendo cyangwa amatike y'ibirori bitabaho, cyangwa bakopera urupapuro rwo gufata icyumba rwa hoteli nyayo bagafata amafaranga mbere.", "Inzu nziza yo kuruhukiramo itangwa ku giciro cya kimwe cya kabiri nushyira avansi uyu munsi kuri mobile money.", "Fata ibyumba unyuze ku mbuga zizwi cyangwa ku rubuga rwemewe rw'ahantu, gereranya igiciro n'isoko, wirinde kwishyura hanze y'urubuga kandi uhamagare ahantu ukoresheje nimero wibonyeye."),
  ("Ulaghai wa uhifadhi, tiketi na malazi bandia", "Wahalifu hutangaza hoteli, nyumba, ndege au tiketi za matukio zisizokuwepo, au kunakili ukurasa wa uhifadhi wa hoteli halisi, na kuchukua malipo mapema.", "Nyumba nzuri ya likizo inatolewa kwa nusu bei ukilipa amana leo kwa pesa za simu.", "Hifadhi kupitia majukwaa maarufu au tovuti rasmi ya mahali pekee, linganisha bei na soko, epuka kulipa nje ya jukwaa na upige mahali kwa namba uliyoipata mwenyewe.")),
"kycscam": S(["kyc scam", "sim registration scam", "sim update scam", "account verification call", "update your kyc", "sim card blocked scam", "id verification scam", "bank kyc update scam"],
  ("Fake KYC, SIM-registration and account-verification scams", "A call or SMS says your SIM, mobile-money or bank account will be blocked unless you 'update your KYC' or 'verify your ID' now, then asks for your ID photo, PIN or a code.", "“Your SIM will be disabled today. Send your ID number and the code we just sent.” The code is the key to your account.", "Update registration only at an official shop or app you open yourself; never give PINs, one-time codes or ID photos to a caller or link, and report the number to your operator."),
  ("Fausses mises à jour KYC, enregistrement SIM et vérification de compte", "Un appel ou SMS dit que votre SIM, compte d'argent mobile ou bancaire sera bloqué si vous ne « mettez pas à jour votre KYC » ou ne « vérifiez pas votre identité » tout de suite, puis demande photo d'identité, PIN ou code.", "« Votre SIM sera désactivée aujourd'hui. Envoyez votre numéro d'identité et le code que nous venons d'envoyer. » Ce code est la clé de votre compte.", "Ne mettez à jour votre enregistrement que dans une boutique officielle ou une appli ouverte par vous-même ; ne donnez jamais PIN, code à usage unique ou photo d'identité à un appelant ou lien et signalez le numéro à votre opérateur."),
  ("Uburiganya bwa KYC, kwandikisha SIM no kugenzura konti by'impimbano", "Guhamagara cyangwa SMS bivuga ko SIM, konti ya mobile money cyangwa ya banki izafungwa nudahindura «KYC» cyangwa ngo «ugenzure indangamuntu» ubu, hanyuma igasaba ifoto y'indangamuntu, PIN cyangwa kode.", "«SIM yawe izafungwa uyu munsi. Ohereza nimero y'indangamuntu na kode tumaze kohereza.» Iyo kode ni urufunguzo rwa konti yawe.", "Vugurura kwiyandikisha gusa ku iduka ryemewe cyangwa porogaramu wifunguriye ubwawe; ntuzigere utanga PIN, kode cyangwa ifoto y'indangamuntu ku uhamagaye cyangwa kuri link kandi umenyeshe nimero sosiyete yawe."),
  ("Ulaghai wa KYC, usajili wa SIM na uhakiki wa akaunti bandia", "Simu au SMS inasema SIM, akaunti ya pesa za simu au ya benki itafungwa usipo «sasisha KYC» au «thibitisha kitambulisho» sasa, kisha kuomba picha ya kitambulisho, PIN au msimbo.", "«SIM yako itazimwa leo. Tuma namba ya kitambulisho na msimbo tuliokutumia.» Msimbo huo ni ufunguo wa akaunti yako.", "Sasisha usajili katika duka rasmi au programu uliyoifungua mwenyewe pekee; kamwe usitoe PIN, msimbo wa mara moja au picha ya kitambulisho kwa mpigaji au kiungo na ripoti namba kwa mtoa huduma wako.")),
"aiimpersonation": S(["ai voice scam", "voice cloning scam", "ai impersonation scam", "deepfake call scam", "ai generated scam", "ai scam", "chatgpt scam", "ai chatbot scam"],
  ("AI voice cloning and AI-generated scams", "Criminals use AI to copy a voice from a short clip, write convincing scam messages in any language, make fake photos or videos of known people, or run chatbots that keep victims talking.", "A call in your manager's voice asks for an urgent payment; a video of a 'celebrity' promotes an investment.", "Do not trust voices, photos or videos alone: hang up and call back on a known number, agree a safe word with family and colleagues, use a second approval for payments and be wary of 'too good' endorsements."),
  ("Clonage de voix par IA et arnaques générées par IA", "Les criminels utilisent l'IA pour copier une voix à partir d'un court extrait, rédiger des messages d'arnaque convaincants dans toutes les langues, fabriquer de fausses photos ou vidéos de personnalités ou animer des chatbots qui retiennent les victimes.", "Un appel avec la voix de votre responsable demande un paiement urgent ; une vidéo d'une « célébrité » promeut un investissement.", "Ne vous fiez pas à une voix, photo ou vidéo seule : raccrochez et rappelez un numéro connu, convenez d'un mot de passe avec famille et collègues, exigez une seconde validation des paiements et méfiez-vous des soutiens « trop beaux »."),
  ("Gukoporora ijwi na AI n'uburiganya bukozwe na AI", "Abagizi ba nabi bakoresha AI mu gukoporora ijwi mu gace gato, kwandika ubutumwa bw'uburiganya bwemeza mu ndimi zose, gukora amafoto cyangwa amashusho y'impimbano y'ibyamamare cyangwa chatbots zikomeza abagirwaho ingaruka.", "Guhamagara hakoreshejwe ijwi ry'umuyobozi wawe risaba kwishyura byihutirwa; videwo y'«icyamamare» yamamaza ishoramari.", "Ntukizere ijwi, ifoto cyangwa videwo ryonyine: hagarika uhamagare nimero uzi, mwemeranye ijambo ry'ibanga n'umuryango n'abakozi, usabe kwemezwa kwa kabiri ku kwishyura kandi wirinde ibyamamazwa «byiza cyane»."),
  ("Kunakili sauti kwa AI na ulaghai unaotengenezwa na AI", "Wahalifu hutumia AI kunakili sauti kutoka klipu fupi, kuandika jumbe za ulaghai zinazoshawishi kwa lugha yoyote, kutengeneza picha au video bandia za watu mashuhuri au kuendesha chatbots zinazowaweka waathirika kwenye mazungumzo.", "Simu kwa sauti ya meneja wako inaomba malipo ya haraka; video ya «mtu mashuhuri» inatangaza uwekezaji.", "Usiamini sauti, picha au video pekee: kata simu na upige tena kwa namba inayojulikana, kubaliana neno la siri na familia na wenzako, tumia idhini ya pili kwa malipo na kuwa makini na uidhinishaji «mzuri kupita kiasi».")),
"healthscam": S(["health scam", "fake cure scam", "miracle cure scam", "fake medicine scam", "fake health insurance scam", "weight loss scam", "fake pharmacy online"],
  ("Fake health, miracle-cure and online-pharmacy scams", "Ads and messages promote miracle cures, unlicensed medicines, fake insurance or 'doctor' accounts to sell products or collect payment and personal data, risking health as well as money.", "A video claims a herbal powder cures diabetes in a week and asks you to order by mobile money.", "Ask a licensed health worker or pharmacist before buying; check products with the national medicines regulator, avoid 'miracle' claims and never stop prescribed treatment because of an online ad."),
  ("Fausses cures miracles, fausses assurances santé et pharmacies en ligne", "Publicités et messages promeuvent des cures miracles, des médicaments sans autorisation, de fausses assurances ou de faux comptes de « médecin » pour vendre ou collecter paiements et données, au risque de la santé comme de l'argent.", "Une vidéo prétend qu'une poudre à base de plantes guérit le diabète en une semaine et demande de commander par argent mobile.", "Demandez à un professionnel de santé ou pharmacien agréé avant d'acheter ; vérifiez le produit auprès du régulateur national des médicaments, méfiez-vous des promesses « miracles » et n'arrêtez jamais un traitement prescrit à cause d'une pub."),
  ("Uburiganya bw'imiti y'igitangaza, ubwishingizi bw'ubuzima bw'impimbano n'amafarumasi yo kuri interineti", "Amamenyesha n'ubutumwa byamamaza imiti y'igitangaza, imiti idafite uruhushya, ubwishingizi bw'impimbano cyangwa konti za «muganga» kugira ngo bagurishe cyangwa bakusanye amafaranga n'amakuru, bishyira ubuzima n'amafaranga mu kaga.", "Videwo ivuga ko ifu y'ibyatsi ikiza diyabete mu cyumweru igasaba gutumiza ukoresheje mobile money.", "Baza umuganga cyangwa umufarumasiye ufite uruhushya mbere yo kugura; genzura ibicuruzwa ku rwego rw'igihugu rugenzura imiti, wirinde ibyizeza «igitangaza» kandi ntuzigere uhagarika imiti wandikiwe kubera itangazo kuri interineti."),
  ("Ulaghai wa tiba za miujiza, bima ya afya bandia na maduka ya dawa mtandaoni", "Matangazo na jumbe hutangaza tiba za miujiza, dawa zisizo na leseni, bima bandia au akaunti za «daktari» kuuza bidhaa au kukusanya malipo na taarifa binafsi, na kuhatarisha afya pamoja na pesa.", "Video inadai unga wa mitishamba unatibu kisukari kwa wiki moja na kukuomba uagize kwa pesa za simu.", "Muulize mhudumu wa afya au mfamasia mwenye leseni kabla ya kununua; hakiki bidhaa kwa mdhibiti wa taifa wa dawa, epuka madai ya «miujiza» na kamwe usiache matibabu uliyoandikiwa kwa sababu ya tangazo mtandaoni.")),
"bettingscam": S(["betting scam", "fixed match scam", "betting tipster scam", "forex scam", "trading signals scam", "fake betting tips", "sure odds scam", "fake forex broker"],
  ("Betting tipster, fixed-match and forex-signal scams", "Fake 'experts' sell guaranteed betting tips, 'fixed matches' or trading signals and managed accounts, using faked winning screenshots, then vanish or claim extra fees to release winnings.", "A channel sells 'sure odds' for 20,000 RWF and shows screenshots of big wins that are edited.", "No one can guarantee bets or trades; do not pay for 'fixed' tips, check brokers with the financial regulator, never hand over account control and only gamble with money you can afford to lose."),
  ("Arnaques aux pronostics, matchs truqués et signaux forex", "De faux « experts » vendent des pronostics garantis, des « matchs arrangés » ou des signaux de trading et comptes gérés, avec des captures de gains truquées, puis disparaissent ou réclament des frais pour libérer les gains.", "Une chaîne vend des « cotes sûres » à 20 000 RWF et montre des captures de gros gains retouchées.", "Personne ne peut garantir un pari ou un trade ; ne payez pas des pronostics « arrangés », vérifiez les courtiers auprès du régulateur financier, ne cédez jamais le contrôle de votre compte et ne jouez qu'avec de l'argent que vous pouvez perdre."),
  ("Uburiganya bw'inama zo guhatana, imikino yateguwe na forex signals", "«Inzobere» z'impimbano zigurisha inama z'ingwate zo guhatana, «imikino yateguwe» cyangwa forex signals n'amakonti acungwa, zikoresha screenshots z'inyungu zahimbwe, hanyuma zigashira cyangwa zigasaba amafaranga yo kurekura inyungu.", "Umuyoboro ugurisha «cote z'ukuri» ku 20,000 RWF ugakoresha screenshots z'inyungu nini zahinduwe.", "Nta muntu ushobora kwizeza ko gutega cyangwa gucuruza kuzatsinda; ntukishyure inama «z'imikino yateguwe», genzura abahuza ku rwego rugenzura imari, ntuzigere utanga kugenzura konti yawe kandi ukine gusa n'amafaranga ushobora gutakaza."),
  ("Ulaghai wa vidokezo vya kubeti, mechi zilizopangwa na ishara za forex", "«Wataalamu» bandia huuza vidokezo vya kubeti vya uhakika, «mechi zilizopangwa» au ishara za biashara na akaunti zinazosimamiwa, kwa picha za skrini za ushindi zilizobuniwa, kisha kutoweka au kudai ada za ziada kuachilia ushindi.", "Chaneli inauza «odds za uhakika» kwa 20,000 RWF na kuonyesha picha za skrini za ushindi mkubwa zilizohaririwa.", "Hakuna anayeweza kuhakikisha kubeti au biashara; usilipe vidokezo vya «mechi zilizopangwa», hakiki madalali kwa mdhibiti wa fedha, kamwe usitoe udhibiti wa akaunti yako na cheza kwa pesa unazoweza kupoteza tu.")),
"examleak": S(["exam leak scam", "exam paper scam", "fake exam results", "exam answers scam", "fake school fees scam", "fake admission scam", "fake university admission", "results scam"],
  ("Exam-leak, fake admission and school-fee scams", "Fraudsters sell 'leaked exam papers', promise guaranteed admission or grades, or send fake fee demands to parents and students, taking money and sometimes getting students in trouble.", "A WhatsApp group sells 'tomorrow's national exam answers' for 5,000 RWF each.", "Exams cannot be bought; pay school or university fees only through the institution's official accounts confirmed by the office, and report fake offers to the school."),
  ("Arnaques aux fuites d'examens, fausses admissions et frais scolaires", "Des fraudeurs vendent des « sujets d'examen fuités », promettent admission ou notes garanties, ou envoient de fausses demandes de frais aux parents et étudiants, prennent l'argent et causent parfois des ennuis aux élèves.", "Un groupe WhatsApp vend les « réponses de l'examen national de demain » à 5 000 RWF chacune.", "On n'achète pas un examen ; ne payez les frais scolaires ou universitaires que sur les comptes officiels de l'établissement confirmés par le bureau et signalez les fausses offres à l'école."),
  ("Uburiganya bw'ibizamini byasohotse, kwemererwa kw'impimbano n'amafaranga y'ishuri", "Abatekamutwe bagurisha «ibibazo by'ikizamini byasohotse», basezeranya kwemererwa cyangwa amanota y'ingwate, cyangwa bohereza ibyifuzo by'impimbano by'amafaranga y'ishuri ku babyeyi n'abanyeshuri, bakabaka amafaranga rimwe na rimwe bagateza abanyeshuri ibibazo.", "Itsinda rya WhatsApp rigurisha «ibisubizo by'ikizamini cya Leta cy'ejo» ku 5,000 RWF buri kimwe.", "Ikizamini ntikigurwa; ishyura amafaranga y'ishuri cyangwa kaminuza gusa kuri konti zemewe z'ikigo zemejwe n'ibiro kandi ubimenyeshe ishuri."),
  ("Ulaghai wa mitihani iliyovuja, udahili bandia na ada za shule", "Walaghai huuza «karatasi za mitihani zilizovuja», kuahidi udahili au alama za uhakika, au kutuma madai bandia ya ada kwa wazazi na wanafunzi, kuchukua pesa na wakati mwingine kuwaingiza wanafunzi matatani.", "Kikundi cha WhatsApp kinauza «majibu ya mtihani wa taifa wa kesho» kwa 5,000 RWF kila moja.", "Mtihani hauwezi kununuliwa; lipa ada za shule au chuo kupitia akaunti rasmi za taasisi zilizothibitishwa na ofisi na ripoti ofa bandia shuleni.")),
"whatsappcode": S(["whatsapp code scam", "whatsapp verification code scam", "whatsapp hijack scam", "whatsapp account stolen", "six digit code scam", "whatsapp group scam", "friend asks for code"],
  ("WhatsApp verification-code and account-hijack scam", "A 'friend' or stranger says they sent you a code by mistake and asks you to read it out; that code lets them register your WhatsApp on their phone, then they message your contacts for money.", "“Hi, I sent my code to your number by mistake, please send it back.” It is your own account's login code.", "Never share a six-digit verification code; turn on two-step verification in WhatsApp, warn contacts if you are hijacked and report the account to WhatsApp."),
  ("Arnaque au code de vérification WhatsApp et détournement de compte", "Un « ami » ou un inconnu dit vous avoir envoyé un code par erreur et demande de le lui lire ; ce code lui permet d'enregistrer votre WhatsApp sur son téléphone, puis il demande de l'argent à vos contacts.", "« Bonjour, j'ai envoyé mon code à votre numéro par erreur, renvoyez-le-moi. » C'est le code de connexion de votre propre compte.", "Ne partagez jamais un code de vérification à six chiffres ; activez la vérification en deux étapes dans WhatsApp, prévenez vos contacts en cas de détournement et signalez le compte à WhatsApp."),
  ("Uburiganya bw'ikode yo kwemeza ya WhatsApp no gufata konti", "«Inshuti» cyangwa umuntu utazi avuga ko yakohereje kode kubw'ikosa agasaba ko uyimubwira; iyo kode imutuma yiyandikisha WhatsApp yawe kuri telefone ye, hanyuma agasaba amafaranga abo muvugana.", "«Muraho, nakohereje kode yanjye kuri nimero yawe kubw'ikosa, nyisubize.» Ni kode yo kwinjira kuri konti yawe bwite.", "Ntuzigere utanga kode y'imibare itandatu; fungura two-step verification muri WhatsApp, umenyeshe abo muvugana iyo konti yawe yafashwe kandi uyimenyeshe WhatsApp."),
  ("Ulaghai wa msimbo wa uthibitisho wa WhatsApp na utekaji wa akaunti", "«Rafiki» au mgeni anasema alikutumia msimbo kimakosa na kukuomba umsomee; msimbo huo unamruhusu kusajili WhatsApp yako kwenye simu yake, kisha kuomba pesa kwa watu wako.", "«Habari, nilituma msimbo wangu kwa namba yako kimakosa, tafadhali nirudishie.» Ni msimbo wa kuingia akaunti yako mwenyewe.", "Kamwe usishiriki msimbo wa tarakimu sita; washa uthibitishaji wa hatua mbili kwenye WhatsApp, waonye watu wako ukitekwa na ripoti akaunti kwa WhatsApp.")),
"atmhelper": S(["atm scam", "atm helper scam", "card swap scam", "atm card trapped scam", "stranger helps at atm", "atm skimming help"],
  ("ATM 'helper' and card-swap scams", "A friendly stranger offers help at an ATM or agent, watches your PIN, swaps your card for another or claims the machine has trapped it, then drains your account.", "“Your card is stuck, let me try; enter your PIN again.” Meanwhile another person has your real card.", "Use ATMs in safe places and cover the keypad, refuse help from strangers, check that your own card comes back and call your bank at once if a card is retained."),
  ("Arnaques de l'« aide » au distributeur et échange de carte", "Un inconnu serviable propose son aide à un distributeur ou agent, observe votre PIN, échange votre carte ou prétend que la machine l'a avalée, puis vide votre compte.", "« Votre carte est bloquée, laissez-moi essayer ; retapez votre PIN. » Pendant ce temps une autre personne a votre vraie carte.", "Utilisez des distributeurs sûrs et cachez le clavier, refusez l'aide d'inconnus, vérifiez que votre carte revient et appelez votre banque aussitôt si une carte est retenue."),
  ("Uburiganya bwo «gufasha» kuri ATM no guhindura karita", "Umuntu utazi wiyoroheje agufasha kuri ATM cyangwa kwa agent, areba PIN yawe, agahindura karita yawe cyangwa avuga ko imashini yayifashe, hanyuma agakuramo amafaranga yose kuri konti yawe.", "«Karita yawe yafashe, reka ngerageze; ongera ushyiremo PIN.» Muri icyo gihe undi muntu afite karita yawe nyayo.", "Koresha ATM ahantu hatekanye kandi utwikire keypad, wange ubufasha bw'abatazwi, urebe ko karita yawe isubira kandi uhamagare banki ako kanya iyo karita yafashwe."),
  ("Ulaghai wa «msaada» ATM na kubadilisha kadi", "Mgeni mwema hutoa msaada kwenye ATM au wakala, kuangalia PIN yako, kubadilisha kadi yako au kudai mashine imeimeza, kisha kutoa pesa zote kwenye akaunti yako.", "«Kadi yako imekwama, acha nijaribu; ingiza PIN tena.» Wakati huo mtu mwingine ana kadi yako halisi.", "Tumia ATM maeneo salama na ufunike kibodi, kataa msaada wa wageni, hakikisha kadi yako inarudi na upige benki mara moja kadi ikizuiliwa.")),
"fakeescrow": S(["fake escrow scam", "escrow scam", "fake payment protection", "fake courier payment", "pay first escrow scam", "safe payment service scam"],
  ("Fake escrow and 'safe payment' services", "In an online sale the scammer proposes a 'trusted escrow or courier service' that is really their own fake website, which collects your payment and never delivers or releases it.", "“Pay through safe-trade-escrow.example and the seller ships tomorrow.” The site is built by the seller.", "Use only the escrow, courier or payment protection of the well-known platform you are on; if the other person suggests another site, treat it as a red flag and walk away."),
  ("Faux séquestre et services de « paiement sécurisé »", "Lors d'une vente en ligne, l'escroc propose un « service de séquestre ou de livraison de confiance » qui est en réalité son propre faux site, lequel encaisse votre paiement sans jamais livrer ni libérer.", "« Payez via safe-trade-escrow.example et le vendeur expédie demain. » Le site est conçu par le vendeur.", "N'utilisez que le séquestre, la livraison ou la protection de paiement de la plateforme connue où vous êtes ; si l'autre propose un autre site, c'est un signal d'alarme : partez."),
  ("Escrow y'impimbano na serivisi za «kwishyura mu buryo butekanye»", "Mu igurisha kuri interineti, umutekamutwe atanga igitekerezo cya «escrow cyangwa serivisi yo kohereza yizewe» nyamara ari urubuga rwe rw'impimbano, rwakira amafaranga yawe ntirutange cyangwa ngo rurekure.", "«Ishyura unyuze kuri safe-trade-escrow.example maze umucuruzi yohereze ejo.» Urwo rubuga rwakozwe n'umucuruzi.", "Koresha gusa escrow, kohereza cyangwa kurinda ubwishyu bya platform uzi uriho; niba undi agusaba urundi rubuga, ni ikimenyetso gikomeye cyo kugenda."),
  ("Escrow bandia na huduma za «malipo salama»", "Katika mauzo ya mtandaoni tapeli hupendekeza «huduma ya escrow au usafirishaji inayoaminika» ambayo kwa kweli ni tovuti yake bandia, inayokusanya malipo yako na kamwe haisafirishi wala kuachilia.", "«Lipa kupitia safe-trade-escrow.example na muuzaji atasafirisha kesho.» Tovuti imejengwa na muuzaji.", "Tumia escrow, usafirishaji au ulinzi wa malipo wa jukwaa maarufu ulilopo tu; mtu mwingine akipendekeza tovuti nyingine, ni alama nyekundu: ondoka.")),
"notificationspam": S(["browser notification scam", "push notification scam", "fake virus alert popup", "pop-up scam", "fake captcha scam", "allow notifications scam", "click allow to continue"],
  ("Browser notification, fake-alert and fake-CAPTCHA scams", "A web page asks you to click 'Allow' to prove you are human or to see a video, then floods your phone with fake virus alerts and scam ads; some fake CAPTCHAs ask you to paste a command that installs malware.", "A page says “Press Allow to confirm you are not a robot” and later your screen shows endless 'virus found' alerts.", "Do not allow notifications from unknown sites, never run commands a web page asks you to paste, remove permissions in browser settings and run a security scan if alerts appear."),
  ("Arnaques aux notifications du navigateur, fausses alertes et faux CAPTCHA", "Une page web demande de cliquer sur « Autoriser » pour prouver que vous êtes humain ou voir une vidéo, puis inonde votre téléphone de fausses alertes de virus et de publicités frauduleuses ; certains faux CAPTCHA demandent de coller une commande qui installe un malware.", "Une page dit « Appuyez sur Autoriser pour confirmer que vous n'êtes pas un robot » et votre écran affiche ensuite des alertes « virus détecté » sans fin.", "N'autorisez pas les notifications de sites inconnus, n'exécutez jamais une commande qu'une page web vous demande de coller, retirez les permissions dans les réglages du navigateur et lancez une analyse si des alertes apparaissent."),
  ("Uburiganya bw'amenyesha ya browser, imburira z'impimbano na CAPTCHA y'impimbano", "Urupapuro rw'urubuga rugusaba gukanda «Allow» ngo ugaragaze ko uri umuntu cyangwa urebe videwo, hanyuma rukuzuza telefone imburira z'impimbano za virusi n'amamenyesha y'uburiganya; zimwe CAPTCHA z'impimbano zisaba gukopera itegeko rishyiraho malware.", "Urupapuro ruvuga «Kanda Allow wemeze ko utari robot» nyuma ecran ikerekana imburira «virusi yabonetse» zidashira.", "Ntukemere amenyesha y'imbuga zitazwi, ntuzigere ukoresha itegeko urupapuro rugusaba gukopera, ukureho uburenganzira mu igenamiterere rya browser kandi ukore isuzuma iyo imburira zigaragaye."),
  ("Ulaghai wa arifa za kivinjari, tahadhari bandia na CAPTCHA bandia", "Ukurasa wa wavuti unakuomba ubofye «Allow» kuthibitisha wewe ni binadamu au kuona video, kisha kujaza simu yako tahadhari bandia za virusi na matangazo ya ulaghai; baadhi ya CAPTCHA bandia zinakuomba ubandike amri inayosakinisha programu hasidi.", "Ukurasa unasema «Bonyeza Allow kuthibitisha wewe si roboti» na baadaye skrini yako inaonyesha tahadhari za «virusi imepatikana» zisizoisha.", "Usiruhusu arifa kutoka tovuti zisizojulikana, kamwe usiendeshe amri ukurasa unakuomba ubandike, ondoa ruhusa kwenye mipangilio ya kivinjari na fanya uchanganuzi arifa zikitokea.")),
"wangiri": S(["wangiri", "one ring scam", "missed call scam", "callback scam", "premium rate scam", "missed call from unknown number", "call back international number scam"],
  ("One-ring (Wangiri) and missed-call callback scams", "Your phone rings once from an unknown (often foreign or premium-rate) number and stops; if you call back you may be charged heavily or kept on a long call, or the call is the first step of a later fraud.", "A missed call from a long international number arrives at 3 a.m.", "Do not call back unknown numbers, especially foreign or short premium ones; block them, use your operator's spam tools and check call charges before returning a missed call."),
  ("Arnaque du « Wangiri » (un seul appel manqué) et rappel", "Votre téléphone sonne une fois depuis un numéro inconnu (souvent étranger ou surtaxé) puis s'arrête ; si vous rappelez, vous pouvez être facturé lourdement ou gardé en ligne, ou l'appel prépare une fraude ultérieure.", "Un appel manqué d'un long numéro international arrive à 3 h du matin.", "Ne rappelez pas les numéros inconnus, surtout étrangers ou surtaxés courts ; bloquez-les, utilisez les outils anti-spam de votre opérateur et vérifiez le coût avant de rappeler un appel manqué."),
  ("Uburiganya bwa «Wangiri» (guhamagara rimwe) no gusubiza guhamagara", "Telefone yawe ivuza rimwe ihamagawe na nimero itazwi (akenshi yo hanze cyangwa ihenze) igahagarara; nuyihamagara ushobora kwishyuzwa menshi cyangwa ugakomeza guhamagara igihe kirekire, cyangwa ni intambwe ya mbere y'uburiganya buzakurikiraho.", "Guhamagara kutitabiwe kuvuye ku nimero ndende yo hanze kuza saa cyenda z'ijoro.", "Ntugahamagare nimero zitazwi, cyane iz'ahandi cyangwa ngufi zihenze; zifunge, ukoreshe ibikoresho birwanya spam bya sosiyete yawe kandi urebe ikiguzi mbere yo gusubiza guhamagara kutitabiwe."),
  ("Ulaghai wa «Wangiri» (mlio mmoja) na kupiga tena", "Simu yako inalia mara moja kutoka namba isiyojulikana (mara nyingi ya nje au ya bei ya juu) na kukata; ukipiga tena unaweza kutozwa sana au kuwekwa kwenye simu ndefu, au simu hiyo ni hatua ya kwanza ya ulaghai wa baadaye.", "Simu ambayo haikupokelewa kutoka namba ndefu ya kimataifa inafika saa 9 usiku.", "Usipige tena namba zisizojulikana, hasa za nje au fupi za bei ya juu; zizuie, tumia zana za kuzuia spam za mtoa huduma wako na angalia gharama kabla ya kupiga tena.")),
"landscam": S(["land scam", "fake land sale", "property scam", "fake title deed", "land title fraud", "fake property seller", "plot sale scam", "house sale scam"],
  ("Land, plot and property sale scams", "Fraudsters sell land or houses they do not own with forged documents, or sell the same plot to several buyers, pushing for a quick deposit before any checks.", "A seller offers a plot at a bargain 'because I am travelling abroad' and only meets you by phone.", "Verify ownership at the official land registry, meet the true owner in person with ID, use a lawyer or notary, pay through traceable channels and never hurry into a deposit."),
  ("Arnaques à la vente de terrains, parcelles et biens immobiliers", "Des fraudeurs vendent des terrains ou maisons qui ne leur appartiennent pas avec de faux documents, ou vendent la même parcelle à plusieurs acheteurs, en pressant pour un acompte rapide avant toute vérification.", "Un vendeur propose une parcelle à prix cassé « parce que je voyage à l'étranger » et ne vous rencontre que par téléphone.", "Vérifiez la propriété au registre foncier officiel, rencontrez le vrai propriétaire en personne avec pièce d'identité, passez par un avocat ou notaire, payez par des canaux traçables et ne vous précipitez jamais pour un acompte."),
  ("Uburiganya bwo kugurisha ubutaka, ibibanza n'amazu", "Abatekamutwe bagurisha ubutaka cyangwa amazu batunze bakoresheje inyandiko z'impimbano, cyangwa bakagurisha ikibanza kimwe ku bantu benshi, bagahatira avansi byihuse mbere y'igenzura.", "Umugurisha atanga ikibanza ku giciro gito «kuko ngiye mu mahanga» akaguhura kuri telefone gusa.", "Genzura nyirubwite ku biro by'ubutaka byemewe, uhure na nyirubwite nyawe ufite indangamuntu, ukoreshe avoka cyangwa noteri, wishyure unyuze mu nzira zikurikiranwa kandi ntuzigere wihutira gutanga avansi."),
  ("Ulaghai wa uuzaji wa ardhi, viwanja na mali", "Walaghai huuza ardhi au nyumba wasizomiliki kwa nyaraka bandia, au kuuza kiwanja kimoja kwa wanunuzi kadhaa, wakisukuma amana ya haraka kabla ya ukaguzi wowote.", "Muuzaji anatoa kiwanja kwa bei ndogo «kwa sababu nasafiri nje ya nchi» na anakutana nawe kwa simu tu.", "Hakiki umiliki kwenye usajili rasmi wa ardhi, kutana na mmiliki halisi ana kwa ana mwenye kitambulisho, tumia wakili au mthibitishaji, lipa kwa njia zinazofuatilika na usiharakishe amana.")),
}
